extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var rock := await instantiate_scene("res://rock.tscn")
	if not check("rock_exists", rock != null, "La scena rock.tscn deve istanziarsi senza errori"):
		return
	if not check("has_hits", has_function(rock, "hits_basket"), "In rock.gd deve esistere la funzione hits_basket"):
		return
	if not check("has_check", has_function(rock, "check_hit"), "In rock.gd deve esistere la funzione check_hit"):
		return
	var hit_dist: float = float(get_prop(rock, "HIT_DISTANCE", 50.0))
	rock.set("position", Vector2(500.0, 500.0))
	var hit_close = call_if_exists(rock, "hits_basket", [Vector2(500.0, 500.0 + hit_dist - 20.0)], false)
	check("hit_within_distance", hit_close == true, "A distanza inferiore a HIT_DISTANCE hits_basket deve restituire true")
	var hit_far = call_if_exists(rock, "hits_basket", [Vector2(500.0, 500.0 + hit_dist + 10.0)], true)
	check("miss_outside_distance", hit_far == false, "A distanza superiore o uguale a HIT_DISTANCE hits_basket deve restituire false")
	rock.set("position", Vector2(400.0, 400.0))
	var miss_dmg = call_if_exists(rock, "check_hit", [Vector2(800.0, 800.0)], -1)
	check("dmg_zero_on_miss", miss_dmg == 0, "Senza collisione check_hit deve restituire 0")
	var pos_after_miss = get_prop(rock, "position", Vector2.ZERO)
	check("no_reset_on_miss", is_equal_approx(pos_after_miss.y, 400.0), "Senza collisione la roccia non deve ripristinarsi")
	rock.set("position", Vector2(500.0, 500.0))
	var current_dmg = get_prop(rock, "damage", 1)
	var dealt_dmg = call_if_exists(rock, "check_hit", [Vector2(500.0, 500.0 + hit_dist - 10.0)], 0)
	check("dmg_returned", dealt_dmg == current_dmg, "In caso di urto check_hit deve restituire il danno inflitto dall'ostacolo")
	var expected_y = float(get_prop(rock, "START_Y", 80.0))
	var pos_after_hit = get_prop(rock, "position", Vector2.ZERO)
	check("reset_on_hit", is_equal_approx(pos_after_hit.y, expected_y), "In caso di urto check_hit deve chiamare reset_rock() riportando la roccia a Y = %.1f" % expected_y)
